css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .8); height: var(--loader-size); position: relative; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; }
.loader::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 4%; border-radius: 999px; background: color-mix(in srgb, #fff 55%, var(--accent-2)); }
.loader::before { content: ''; position: absolute; top: 2%; left: 32%; width: 36%; height: 11%; border-radius: 3px 3px 0 0; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 28%, var(--accent-2))); box-shadow: 0 0 0 calc(var(--loader-size) * .022) color-mix(in srgb, #000 28%, var(--accent-2)); animation: build calc(var(--loader-speed) * 3) ease-out infinite; animation-delay: calc(var(--loader-speed) * .54); }
.loader span { border-radius: 50%; background: radial-gradient(circle at 36% 30%, #fff, color-mix(in srgb, #fff 62%, var(--accent))); box-shadow: inset 0 calc(var(--loader-size) * -.02) calc(var(--loader-size) * .04) color-mix(in srgb, var(--accent) 45%, transparent); animation: build calc(var(--loader-speed) * 3) ease-out infinite; }
.loader span:nth-child(1) { width: 46%; height: calc(var(--loader-size) * .368); order: 3; }
.loader span:nth-child(2) { width: 34%; height: calc(var(--loader-size) * .272); order: 2; margin-bottom: -4%; animation-delay: calc(var(--loader-speed) * .27); }
.loader span:nth-child(3) { width: 25%; height: calc(var(--loader-size) * .2); order: 1; margin-bottom: -3%; animation-delay: calc(var(--loader-speed) * .54); }
@keyframes build { 0% { opacity: 0; transform: scale(0); } 10% { opacity: 1; transform: scale(1.14); } 16% { transform: scale(1); } 80% { opacity: 1; transform: scale(1); } 92%, 100% { opacity: 0; transform: scale(0); } }
